<?php require __DIR__.'/config.php';require_login();$type=$_GET['type']??'applications';if(!in_array($type,['applications','enquiries'],true))$type='applications';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$items=read_json($type);$id=(int)$_POST['id'];foreach($items as &$x)if((int)$x['id']===$id)$x['status']=trim($_POST['status']??'New');unset($x);write_json($type,$items);flash('Status updated.');redirect('inbox.php?type='.$type);}$rows=read_json($type);usort($rows,fn($a,$b)=>strcmp($b['created_at']??'',$a['created_at']??''));?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h(ucfirst($type))?> — Ridgefield CMS</title><link rel="stylesheet" href="cms.css"><link rel="stylesheet" href="assets/dynamic-site.css">
</head><body class="rf-dynamic"><div class="layout"><aside class="sidebar"><div class="brand">A C A D E M Y<small>RIDGEFIELD CMS</small></div><nav><a href="index.php">Dashboard</a><a href="manage.php?type=news">News & Events</a><a href="manage.php?type=staff">Staff</a><a href="manage.php?type=fees">Fees</a><a href="manage.php?type=documents">Documents</a><a class="active" href="inbox.php?type=applications">Applications</a><a class="active" href="inbox.php?type=enquiries">Enquiries</a><a href="settings.php">Site Settings</a><a href="../index.html" target="_blank">View Website ↗</a><a href="logout.php">Sign out</a></nav></aside><div class="main"><header class="topbar"><strong><?=h(ucfirst($type))?></strong></header><main class="content"><div class="page-title"><div><h1><?=h(ucfirst($type))?></h1><p>Review incoming website submissions.</p></div></div><?php if($flash=get_flash()):?><div class="alert success"><?=h($flash[1])?></div><?php endif;?><section class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Person</th><th>Contact</th><th>Details</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['created_at'])?></td><td><strong><?=h($r[$type==='applications'?'learner_name':'name'])?></strong><?php if($type==='applications'):?><br>Guardian: <?=h($r['guardian_name'])?><?php endif;?></td><td><?=h($r['email'])?><br><?=h($r['phone'])?></td><td><?php if($type==='applications'):?>Grade: <?=h($r['grade'])?><br>Curriculum: <?=h($r['curriculum'])?><br><?=nl2br(h($r['message']))?><?php else:?><strong><?=h($r['subject'])?></strong><br><?=nl2br(h($r['message']))?><?php endif;?></td><td><form method="post" class="actions"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><option <?=($r['status']==='New'?'selected':'')?>>New</option><option <?=($r['status']==='Contacted'?'selected':'')?>>Contacted</option><option <?=($r['status']==='In progress'?'selected':'')?>>In progress</option><option <?=($r['status']==='Closed'?'selected':'')?>>Closed</option></select><button class="btn secondary">Save</button></form></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5" class="muted">No submissions yet.</td></tr><?php endif;?></tbody></table></div></section></main></div></div><script src="assets/dynamic-site.js"></script>
</body></html>
